def default_language():
    try:
        return "ru" if ctypes.windll.kernel32.GetUserDefaultUILanguage() & 0x3ff == 0x19 else "en"
    except (AttributeError, OSError):
        return "en"


def resolve_language(value):
    return value if value in ("ru", "en") else default_language()


def text(key, language):
    return TEXT[key][0 if language == "ru" else 1]


def save_language(config_manager, language):
    if language not in ("ru", "en"):
        raise ValueError("Unsupported UI language")
    path = Path(config_manager.user_settings_path)
    yaml = YAML()
    yaml.preserve_quotes = True
    with path.open(encoding="utf-8") as stream:
        data = yaml.load(stream) or {}
    data.setdefault("system_tray", {})["language"] = language
    # Preserve all other YAML values/comments; replace only after a complete write.
    fd, temporary = tempfile.mkstemp(prefix=".ui-language-", suffix=".tmp", dir=path.parent)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as stream:
            yaml.dump(data, stream)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    config_manager.config.setdefault("system_tray", {})["language"] = language


def startup_language():
    try:
        path = Path(os.environ["APPDATA"]) / "whisperkey/user_settings.yaml"
        with path.open(encoding="utf-8") as stream:
            data = YAML(typ="safe").load(stream) or {}
        return resolve_language(data.get("system_tray", {}).get("language"))
    except Exception:
        return default_language()
